t.script:
//
lucide.createIcons();

    function openModal(titleText) {
      document.getElementById('modal-input-platform').value = titleText;
      document.getElementById('modal-title').innerText = titleText;
      const m = document.getElementById('modal-container');
      m.classList.remove('hidden');
      m.classList.add('flex');
    }

    function closeModal() {
      const m = document.getElementById('modal-container');
      m.classList.add('hidden');
      m.classList.remove('flex');
      document.getElementById('modal-form').classList.remove('hidden');
      document.getElementById('modal-success').classList.add('hidden');
    }

    function handleInquirySubmit(e) {
      e.preventDefault();
      document.getElementById('modal-form').classList.add('hidden');
      document.getElementById('modal-success').classList.remove('hidden');
      lucide.createIcons();
    }

    function calculateCustom() {
      const sel = document.getElementById('custom-type');
      const opt = sel.options[sel.selectedIndex];
      let price = parseInt(opt.getAttribute('data-price') || '0', 10);
      let sprints = parseInt(opt.getAttribute('data-sprints') || '4', 10);

      if (document.getElementById('add-telebirr-cbe').checked) {
        price += 50000;
      }

      document.getElementById('custom-total-etb').innerHTML = 
        price.toLocaleString() + ' <span class="text-lg text-slate-400">ETB</span>';
      document.getElementById('custom-sprints').innerHTML = 
        '<i data-lucide="zap" class="w-3.5 h-3.5"></i> ' + sprints + ' Agile Sprints (' + (sprints * 2) + ' Wks)';
      lucide.createIcons();
    }

    window.addEventListener('DOMContentLoaded', calculateCustom);
//
